-- 593: Foundation guard for Cambridge IGCSE Chemistry (0620) sprint 3 beta batch (igcse-chemistry-sprint3-001).
-- Original BrillaPrep practice content; not official Cambridge International, WAEC or NSMQ examination material.
-- Re-asserts the prod-canonical topic rows for subj_igcse_chemistry on scratch
-- baselines; INSERT OR IGNORE no-ops on prod and on fresh baselines where the
-- rows already exist (prod patch 096).
PRAGMA foreign_keys = ON;
INSERT OR IGNORE INTO exam_boards (id, name, code, full_name, region, website_url, is_active, display_order) VALUES ('board_cambridge', 'Cambridge International', 'CAIE', 'Cambridge International Education', 'International', 'https://www.cambridgeinternational.org/', 1, 2);
CREATE TABLE IF NOT EXISTS question_content_releases (
    question_id TEXT PRIMARY KEY REFERENCES questions(id) ON DELETE CASCADE,
    batch_id TEXT NOT NULL,
    quality_assurance TEXT NOT NULL CHECK (quality_assurance IN ('automated_beta', 'human_reviewed')),
    release_channel TEXT NOT NULL CHECK (release_channel IN ('beta', 'production')),
    content_label TEXT NOT NULL,
    source_url TEXT NOT NULL,
    official_exam_board_content INTEGER NOT NULL DEFAULT 0 CHECK (official_exam_board_content IN (0, 1)),
    feedback_enabled INTEGER NOT NULL DEFAULT 1 CHECK (feedback_enabled IN (0, 1)),
    released_at TEXT NOT NULL DEFAULT (datetime('now'))
  );
CREATE INDEX IF NOT EXISTS idx_question_content_releases_batch ON question_content_releases(batch_id);
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_igcse_chem_atomic', 'subj_igcse_chemistry', NULL, 'Matter and Atomic Structure', 'igcse-chem-atomic', 'Particles, atomic structure, isotopes and electron arrangement.', 'Atomic structure covers protons, neutrons and electrons, the meaning of proton and nucleon numbers, isotopes, and the electron arrangements of the first twenty elements.', '["neutrons = nucleon number − proton number", "Group number = outer-shell electrons", "Period number = occupied shells"]', 1, '2026-08-13T00:00:00.000Z');
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_igcse_chem_periodic', 'subj_igcse_chemistry', NULL, 'The Periodic Table', 'igcse-chem-periodic', 'Groups, periods, trends and transition elements.', 'The Periodic Table arranges elements by proton number; group trends cover the alkali metals, the halogens and the noble gases, and position predicts electron arrangement and reactivity.', '["Reactivity of Group I increases down the group", "Reactivity of Group VII decreases down the group", "Ar = Σ(% abundance × mass number)/100"]', 2, '2026-08-13T00:00:00.000Z');
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_igcse_chem_bonding', 'subj_igcse_chemistry', NULL, 'Chemical Bonding', 'igcse-chem-bonding', 'Ionic, covalent and metallic bonding, structure and properties.', 'Bonding explains how atoms achieve full outer shells by transferring or sharing electrons, and how giant ionic, simple molecular, giant covalent and metallic structures determine physical properties.', '["Ionic: metal + non-metal, electrons transferred", "Covalent: non-metal + non-metal, electrons shared", "Giant lattices have high melting points"]', 3, '2026-08-13T00:00:00.000Z');
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_igcse_chem_stoichiometry', 'subj_igcse_chemistry', NULL, 'Stoichiometry', 'igcse-chem-stoichiometry', 'The mole, reacting masses, concentrations and gas volumes.', 'Stoichiometry uses the mole to relate masses, concentrations and gas volumes through balanced equations: moles = mass ÷ Mr, and the coefficients of an equation give the reacting mole ratios.', '["n = m/Mr", "concentration = moles/volume (dm³)", "1 mole of gas = 24 dm³ at r.t.p."]', 4, '2026-08-13T00:00:00.000Z');
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_igcse_chem_reactions', 'subj_igcse_chemistry', NULL, 'Reactions, Rates and Energetics', 'igcse-chem-reactions', 'Rate of reaction, reversible reactions and energy changes.', 'Collision theory explains how concentration, pressure, surface area, temperature and catalysts change the rate of reaction; energetics compares the energy taken in to break bonds with the energy released when new bonds form.', '["ΔH = energy in (bonds broken) − energy out (bonds formed)", "Rate ∝ frequency of successful collisions", "Catalyst lowers the activation energy"]', 5, '2026-08-13T00:00:00.000Z');
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_igcse_chem_acids', 'subj_igcse_chemistry', NULL, 'Acids, Bases and Salts', 'igcse-chem-acids', 'Properties, neutralisation and preparation of salts.', 'Acids release H⁺(aq) ions and bases neutralise them to form salts; the pH scale measures acidity, and pure soluble or insoluble salts are prepared by neutralisation, titration or precipitation.', '["acid + alkali → salt + water", "acid + metal → salt + hydrogen", "acid + carbonate → salt + water + carbon dioxide"]', 6, '2026-08-13T00:00:00.000Z');
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_igcse_chem_metals', 'subj_igcse_chemistry', NULL, 'Metals and Reactivity', 'igcse-chem-metals', 'Reactivity series, extraction, corrosion and alloys.', 'The reactivity series orders metals by their reactions with water, steam and acids; it predicts displacement reactions, the extraction method (electrolysis or carbon reduction) and resistance to corrosion.', '["K > Na > Ca > Mg > Al > Zn > Fe > Pb > Cu > Ag", "More reactive metal displaces less reactive from its salt", "Rusting requires oxygen and water"]', 7, '2026-08-13T00:00:00.000Z');
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_igcse_chem_organic', 'subj_igcse_chemistry', NULL, 'Organic Chemistry', 'igcse-chem-organic', 'Alkanes, alkenes, alcohols, acids and polymers.', 'Organic chemistry studies carbon compounds in homologous series: alkanes, alkenes, alcohols and carboxylic acids, their characteristic reactions, and the addition polymerisation of alkenes.', '["Alkanes CₙH₂ₙ₊₂; alkenes CₙH₂ₙ", "Alcohol + carboxylic acid → ester + water", "Cracking: long alkane → shorter alkane + alkene"]', 8, '2026-08-13T00:00:00.000Z');
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_igcse_chem_electrolysis', 'subj_igcse_chemistry', NULL, 'Electrolysis', 'igcse-chem-electrolysis', 'Products of electrolysis of molten and aqueous ionic compounds.', 'Electrolysis decomposes an ionic compound, molten or in aqueous solution, using a direct current: cations move to the cathode (reduction) and anions to the anode (oxidation); in aqueous solution the reactivity series and concentration decide which ions discharge.', '["Cathode: negative electrode, reduction", "Anode: positive electrode, oxidation", "Concentrated aqueous NaCl → H₂ + Cl₂"]', 9, '2026-08-13T00:00:00.000Z');
INSERT OR IGNORE INTO topics (id, subject_id, parent_id, name, slug, description, theory_content, key_formulas, display_order, created_at) VALUES ('topic_igcse_chem_analysis', 'subj_igcse_chemistry', NULL, 'Experimental Techniques and Chemical Analysis', 'igcse-chem-analysis', 'Tests for gases, cations and anions, and chromatography.', 'Chemical analysis identifies substances with flame tests for cations, precipitation tests for anions, chemical tests for gases, and paper chromatography with Rf values for coloured mixtures.', '["Rf = distance by substance ÷ distance by solvent", "Cl⁻: white precipitate with AgNO₃ after dilute HNO₃", "Na⁺ yellow, K⁺ lilac, Ca²⁺ brick-red flames"]', 10, '2026-08-13T00:00:00.000Z');
CREATE TABLE IF NOT EXISTS _migration_593_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_593_guard;
INSERT INTO _migration_593_guard(valid) SELECT CASE WHEN EXISTS (SELECT 1 FROM exam_types WHERE id = 'igcse') AND EXISTS (SELECT 1 FROM exam_boards WHERE id = 'board_cambridge') AND EXISTS (SELECT 1 FROM subjects WHERE id = 'subj_igcse_chemistry' AND exam_type_id = 'igcse') AND (SELECT COUNT(*) FROM topics t JOIN subjects s ON s.id = t.subject_id WHERE t.id IN ('topic_igcse_chem_atomic', 'topic_igcse_chem_periodic', 'topic_igcse_chem_bonding', 'topic_igcse_chem_stoichiometry', 'topic_igcse_chem_reactions', 'topic_igcse_chem_acids', 'topic_igcse_chem_metals', 'topic_igcse_chem_organic', 'topic_igcse_chem_electrolysis', 'topic_igcse_chem_analysis') AND t.subject_id = 'subj_igcse_chemistry' AND s.exam_type_id = 'igcse') = 10 THEN 1 ELSE 0 END;
DROP TABLE _migration_593_guard;
